def is_ascii(text):
    """Check if a unicode or bytestring, *text*, is composed of ascii
    characters only. Raises :exc:`ValueError` if argument is not text.

    Args:
        text (str or unicode): The string to be checked.

    >>> is_ascii('Beyoncé')
    False
    >>> is_ascii('Beyonce')
    True
    """
    if isinstance(text, unicode):
        try:
            text.encode('ascii')
        except UnicodeEncodeError:
            return False
    elif isinstance(text, bytes):
        try:
            text.decode('ascii')
        except UnicodeDecodeError:
            return False
    else:
        raise ValueError('expected text or bytes, not %r' % type(text))
    return True

def __missing__(self, key):
    ch = self.get(key)
    if ch is not None:
        return ch
    try:
        de = unicodedata.decomposition(unichr(key))
        p1, _, p2 = de.rpartition(' ')
        if int(p2, 16) == 0x308:
            ch = self.get(key)
        else:
            ch = int(p1, 16)
    except (IndexError, ValueError):
        ch = self.get(key, key)
    self[key] = ch
    return ch

