def __reversed__(self):
    root = self.root
    curr = root[PREV]
    lengths = {}
    lengths_sd = lengths.setdefault
    get_values = super(OrderedMultiDict, self).__getitem__
    while curr is not root:
        k = curr[KEY]
        vals = get_values(k)
        if lengths_sd(k, 1) == len(vals):
            yield k
        lengths[k] += 1
        curr = curr[PREV]

