def __repr__(self):
    if self._included is None:
        return 'complement({0})'.format(repr(self._excluded))
    return 'complement(complement({0}))'.format(repr(self._included))

def _calc_pearson_type(self):
    precision = self._pearson_precision
    skewness = self.skewness
    kurtosis = self.kurtosis
    beta1 = skewness ** 2.0
    beta2 = kurtosis * 1.0

    # TODO: range checks?

    c0 = (4 * beta2) - (3 * beta1)
    c1 = skewness * (beta2 + 3)
    c2 = (2 * beta2) - (3 * beta1) - 6

    if round(c1, precision) == 0:
        if round(beta2, precision) == 3:
            return 0  # Normal
        else:
            if beta2 < 3:
                return 2  # Symmetric Beta
            elif beta2 > 3:
                return 7
    elif round(c2, precision) == 0:
        return 3  # Gamma
    else:
        k = c1 ** 2 / (4 * c0 * c2)
        if k < 0:
            return 1  # Beta
    raise RuntimeError('missed a spot')

