def __next__(self):
    if os.getpid() != self.pid:
        self.reseed()
    target_bytes = (self.salt + str(next(self.count))).encode('utf8')
    hash_text = self._sha1(target_bytes).hexdigest()[:self.size]
    return hash_text

def __next__(self):
    if os.getpid() != self.pid:
        self.reseed()
    return self._sha1(self.salt +
                      str(next(self.count))).hexdigest()[:self.size]

def sort(self, **kwargs):
    "sort() -> sort the contents of the set in-place"
    sorted_list = sorted(self, **kwargs)
    if sorted_list == self.item_list:
        return
    self.item_list[:] = sorted_list
    for i, item in enumerate(self.item_list):
        self.item_index_map[item] = i
    del self.dead_indices[:]

def __lt__(self, other):
    obj = key(self.obj) if key is not None else self.obj
    other = key(other.obj) if key is not None else other.obj
    try:
        ret = obj < other
    except TypeError:
        ret = ((type(obj).__name__, id(type(obj)), obj)
                < (type(other).__name__, id(type(other)), other))
    return ret

def __lt__(self, other):
    inc, exc = _norm_args_notimplemented(other)
    if inc is NotImplemented:
        return NotImplemented
    if inc is NotImplemented:
        return NotImplemented
    if self._included is None:
        if exc is None:  # - +
            return False
        else:  # - -
            return self._excluded > exc
    else:
        if inc is None:  # + -
            return self._included.isdisjoint(exc)
        else:  # + +
            return self._included < inc

def __gt__(self, other):
    inc, exc = _norm_args_notimplemented(other)
    if inc is NotImplemented:
        return NotImplemented
    if self._included is None:
        if exc is None:  # - +
            return not self._excluded.intersection(inc)
        else:  # - -
            return self._excluded < exc
    else:
        if inc is None:  # + -
            return False
        else:  # + +
            return self._included > inc

def _cardinalize_time_unit(unit, value):
    # removes dependency on strutils; nice and simple because
    # all time units cardinalize normally
    if value == 1:
        return unit
    return unit + 's'

def utcoffset(self, dt):
    if self.is_dst(dt):
        return self._dst_offset
    return self._std_offset

def dst(self, dt):
    if self.is_dst(dt):
        return self._dst_offset - self._std_offset
    return ZERO

def _first_sunday_on_or_after(dt):
    days_to_go = 6 - dt.weekday()
    if days_to_go:
        dt += timedelta(days_to_go)
    return dt

def tzname(self, dt):
    if self.dst(dt):
        return self.dstname
    else:
        return self.stdname

def dst(self, dt):
    if dt is None or dt.tzinfo is None:
        # An exception may be sensible here, in one or both cases.
        # It depends on how you want to treat them.  The default
        # fromutc() implementation (called by the default astimezone()
        # implementation) passes a datetime with dt.tzinfo is self.
        return ZERO
    assert dt.tzinfo is self

    # Find start and end times for US DST. For years before 1967, return
    # ZERO for no DST.
    if 2006 < dt.year:
        dststart, dstend = DSTSTART_2007, DSTEND_2007
    elif 1986 < dt.year < 2007:
        dststart, dstend = DSTSTART_1987_2006, DSTEND_1987_2006
    elif 1966 < dt.year < 1987:
        dststart, dstend = DSTSTART_1967_1986, DSTEND_1967_1986
    else:
        return ZERO

    start = _first_sunday_on_or_after(dststart.replace(year=dt.year))
    end = _first_sunday_on_or_after(dstend.replace(year=dt.year))

    # Can't compare naive to aware objects, so strip the timezone
    # from dt first.
    if start <= dt.replace(tzinfo=None) < end:
        return HOUR
    else:
        return ZERO

